#include <cstddef>
#include <cassert>
#include <iostream>
#include <vector>

struct EventNode { int code; const EventNode* next; };

// 값이 아니라 동일한 원본 객체를 공유하는 첫 지점을 반환합니다.
// 전제: 두 체인은 유효한 유한 비순환 리스트이며 호출 중 변하지 않습니다.
const EventNode* FindSharedEvent(const EventNode* a, const EventNode* b) {
    std::size_t na = 0, nb = 0;
    for (const EventNode* p = a; p; p = p->next) ++na;
    for (const EventNode* p = b; p; p = p->next) ++nb;
    // 긴 쪽의 독립 접두부만 먼저 소비해 남은 길이를 맞춥니다.
    while (na > nb) { a = a->next; --na; }
    while (nb > na) { b = b->next; --nb; }
    // 같은 거리를 남긴 두 포인터를 함께 이동합니다.
    while (a != b) { a = a->next; b = b->next; }
    return b; // 종료 시 a == b이므로 공통 노드 또는 둘 다 nullptr
}

// 테스트 전용 독립 기준 구현: 추가 공간 허용, 주소로만 비교합니다.
const EventNode* Oracle(const EventNode* a, const EventNode* b) {
    for (const EventNode* p = a; p; p = p->next)
        for (const EventNode* q = b; q; q = q->next)
            if (p == q) return p;
    return nullptr;
}
int main() {
    std::vector<EventNode> fixture(6);
    EventNode &tail=fixture[0], &join=fixture[1], &a2=fixture[2];
    EventNode &a1=fixture[3], &b1=fixture[4], &sameValue=fixture[5];
    tail={7,nullptr}; join={7,&tail}; a2={3,&join};
    a1={1,&a2}; b1={7,&join}; sameValue={7,nullptr};
    assert(FindSharedEvent(&a1, &b1) == &join);
    assert(FindSharedEvent(&b1, &a1) == &join);
    assert(FindSharedEvent(&a1, &a1) == &a1);
    assert(FindSharedEvent(&join, &a1) == &join);
    assert(FindSharedEvent(&tail, &sameValue) == nullptr);
    assert(FindSharedEvent(nullptr, nullptr) == nullptr);
    assert(FindSharedEvent(nullptr, &a1) == nullptr);
    assert(FindSharedEvent(&a1, nullptr) == nullptr);
    assert(a1.next == &a2 && a2.next == &join && b1.next == &join);
    // 작은 DAG 전수 검사: next는 큰 첨자 또는 null이므로 비순환입니다.
    // 값을 모두 같게 두어 값 비교로 잘못 구현한 경우를 검출합니다.
    std::size_t cases = 0;
    for (int n = 0; n <= 6; ++n) {
        std::size_t configs = 1;
        for (int i = 0; i < n; ++i) configs *= static_cast<std::size_t>(n-i);
        for (std::size_t c = 0; c < configs; ++c) {
            std::vector<EventNode> nodes(static_cast<std::size_t>(n));
            std::size_t digits = c;
            for (int i = 0; i < n; ++i) {
                const std::size_t choices = static_cast<std::size_t>(n-i);
                const std::size_t offset = digits % choices;
                digits /= choices;
                nodes[i].code = 7;
                nodes[i].next = offset == 0 ? nullptr : &nodes[i+static_cast<int>(offset)];
            }
            const std::vector<EventNode> before = nodes;
            for (int i = -1; i < n; ++i) for (int j = -1; j < n; ++j) {
                const EventNode* a = i < 0 ? nullptr : &nodes[i];
                const EventNode* b = j < 0 ? nullptr : &nodes[j];
                assert(FindSharedEvent(a,b) == Oracle(a,b));
                for (int k = 0; k < n; ++k)
                    assert(nodes[k].code == before[k].code && nodes[k].next == before[k].next);
                ++cases;
            }
        }
    }
    // 소유 벡터를 먼저 확보하고 연결 후에는 재할당하지 않습니다.
    std::vector<EventNode> longChain(100000);
    for (std::size_t i=0; i<longChain.size(); ++i) {
        longChain[i].code = 0;
        longChain[i].next = i+1<longChain.size() ? &longChain[i+1] : nullptr;
    }
    assert(FindSharedEvent(&longChain[0], &longChain[99999]) == &longChain[99999]);
    std::cout << "PASS: 8 boundary assertions, " << cases
              << " exhaustive DAG head pairs, 100000-node skew, link/value preservation\n";
}
